        Map<String, Charset> mockCommonCharsets = new HashMap<>();
        mockCommonCharsets.put("windows-1252", mockCharset);
        when(CharsetUtils.COMMON_CHARSETS.get("windows-1252")).thenReturn(mockCharset);
        when(getCharsetICU.invoke(null, "windows-1252")).thenReturn(mockCharset);
        Charset result = charsetUtils.forName("win-1252");
        assertEquals(mockCharset, result);
    }

    @Test
    public void testForName_withICUCharset() throws Exception {
        Charset mockCharset = mock(Charset.class);
        when(getCharsetICU.invoke(null, "utf-8")).thenReturn(mockCharset);
        Charset result = charsetUtils.forName("utf-8");
        assertEquals(mockCharset, result);
    }
